blocky.profile:
@prefix ga:     <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix blocky: <https://tesseractsemantics.com/ns/asset-passport/blocky#> .
@prefix owl:    <http://www.w3.org/2002/07/owl#> .
@prefix rdfs:   <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:    <http://www.w3.org/2001/XMLSchema#> .

# Blocky: a top-down block miner. One length unit is one block, and one block
# is one metre. A player has 20 hit points, drawn as ten hearts. Every number
# is a whole number. There is no stamina, no poise and no checkpoint: a player
# who dies wakes at the last bed they slept in.

blocky:game a ga:Game ;
    rdfs:label "Blocky" ;
    ga:maxPlayerHealth 20 ;
    ga:metresPerLengthUnit 1.0 ;
    ga:maxArmourRating 20 ;
    ga:damageReductionAtMaxArmour 0.8 ;
    ga:wholeNumbersOnly true .

# ---------------------------------------------- Blocky's own words, mapped into the hub

blocky:Item a owl:Class ; rdfs:subClassOf ga:Item ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ga:fromGame ; owl:hasValue blocky:game ] .

blocky:DiamondSword a owl:Class ; rdfs:subClassOf ga:MeleeWeapon ; rdfs:label "Diamond sword" .
blocky:IronChestplate a owl:Class ; rdfs:subClassOf ga:BodyArmour ; rdfs:label "Iron chestplate" .
blocky:Bed a owl:Class ; rdfs:subClassOf ga:RespawnAnchor ; rdfs:label "Bed" .

blocky:attack a owl:DatatypeProperty ; rdfs:subPropertyOf ga:baseDamage .
blocky:size a owl:DatatypeProperty ; rdfs:subPropertyOf ga:length .
blocky:armorPoints a owl:DatatypeProperty ; rdfs:subPropertyOf ga:armourRating .
blocky:heals a owl:DatatypeProperty ; rdfs:subPropertyOf ga:healAmount .
blocky:name a owl:DatatypeProperty ; rdfs:subPropertyOf rdfs:label .

souls.profile:
@prefix ga:    <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix souls: <https://tesseractsemantics.com/ns/asset-passport/souls#> .
@prefix owl:   <http://www.w3.org/2002/07/owl#> .
@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:   <http://www.w3.org/2001/XMLSchema#> .

# Ashen: a side-on souls-like duel. One length unit is one centimetre. A player
# has 1,000 hit points. Armour is absorption in percent. Every swing costs
# stamina, poise decides who staggers, and death sends the player back to the
# last bonfire, which also refills the flask. The bonfire is the whole loop.

souls:game a ga:Game ;
    rdfs:label "Ashen" ;
    ga:maxPlayerHealth 1000 ;
    ga:metresPerLengthUnit 0.01 ;
    ga:maxArmourRating 100 ;
    ga:damageReductionAtMaxArmour 1.0 ;
    ga:defaultStaminaCost 18 ;
    ga:wholeNumbersOnly true .

# ---------------------------------------------- Ashen's own words, mapped into the hub

souls:Item a owl:Class ; rdfs:subClassOf ga:Item ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ga:fromGame ; owl:hasValue souls:game ] .

souls:Greatsword a owl:Class ; rdfs:subClassOf ga:TwoHandedWeapon ; rdfs:label "Greatsword" .
souls:EmberFlask a owl:Class ; rdfs:subClassOf ga:HealingConsumable ; rdfs:label "Ember flask" .
souls:KnightArmour a owl:Class ; rdfs:subClassOf ga:BodyArmour ; rdfs:label "Knight armour" .

souls:attackRating a owl:DatatypeProperty ; rdfs:subPropertyOf ga:baseDamage .
souls:bladeLengthCm a owl:DatatypeProperty ; rdfs:subPropertyOf ga:length .
souls:absorption a owl:DatatypeProperty ; rdfs:subPropertyOf ga:armourRating .
souls:restoresHp a owl:DatatypeProperty ; rdfs:subPropertyOf ga:healAmount .
souls:poiseDamage a owl:DatatypeProperty ; rdfs:subPropertyOf ga:poise .
souls:stamina a owl:DatatypeProperty ; rdfs:subPropertyOf ga:staminaCost .
souls:refillsAtBonfire a owl:DatatypeProperty ; rdfs:subPropertyOf ga:refillsAtCheckpoint .
souls:name a owl:DatatypeProperty ; rdfs:subPropertyOf rdfs:label .

files.hub:
@prefix ga:   <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

# The Game Asset core. It is the hub every game maps INTO, so N games need N
# mappings, not N squared. It says what an item IS. It does not say what an item
# is worth in any one game: numbers stay in the source game's own units until
# the receiving game's declared conversion policy turns them into its units.

<https://tesseractsemantics.com/ns/asset-passport/ga> a owl:Ontology ;
    rdfs:label "Asset Passport: Game Asset core" ;
    owl:versionInfo "0.1.0" .

# ---------------------------------------------------------------- what an item is

ga:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "Anything a player can carry from one game into another." .

ga:Weapon a owl:Class ; rdfs:subClassOf ga:Item ; rdfs:label "Weapon" .

ga:MeleeWeapon a owl:Class ; rdfs:subClassOf ga:Weapon ;
    rdfs:label "Melee weapon" ;
    rdfs:comment "A weapon whose reach is its own length." .

ga:TwoHandedWeapon a owl:Class ; rdfs:subClassOf ga:MeleeWeapon ;
    rdfs:label "Two-handed weapon" .

ga:Armour a owl:Class ; rdfs:subClassOf ga:Item ; rdfs:label "Armour" .

ga:BodyArmour a owl:Class ; rdfs:subClassOf ga:Armour ; rdfs:label "Body armour" .

ga:Consumable a owl:Class ; rdfs:subClassOf ga:Item ; rdfs:label "Consumable" .

ga:HealingConsumable a owl:Class ; rdfs:subClassOf ga:Consumable ;
    rdfs:label "Healing consumable" .

ga:RespawnAnchor a owl:Class ; rdfs:subClassOf ga:Item ;
    rdfs:label "Respawn anchor" ;
    rdfs:comment "An item that moves the point where a player comes back after death. It changes the rules of death in the receiving game, not only the player's power." .

ga:Game a owl:Class ; rdfs:label "Game" .

# ---------------------------------------------------- what an item has, in source units

ga:fromGame a owl:ObjectProperty ;
    rdfs:label "from game" ;
    rdfs:comment "The game whose units every number on this item is written in." ;
    rdfs:range ga:Game .

ga:importTarget a owl:ObjectProperty ;
    rdfs:label "import target" ;
    rdfs:comment "The customs declaration: the receiving game states it, and the conversion rule reads it." ;
    rdfs:range ga:Game .

ga:baseDamage a owl:DatatypeProperty ;
    rdfs:label "base damage" ;
    rdfs:comment "Damage of one hit, in hit points of the source game." .

ga:length a owl:DatatypeProperty ;
    rdfs:label "length" ;
    rdfs:comment "Length in the source game's length unit." .

ga:armourRating a owl:DatatypeProperty ;
    rdfs:label "armour rating" ;
    rdfs:comment "Protection on the source game's own armour scale." .

ga:healAmount a owl:DatatypeProperty ;
    rdfs:label "heal amount" ;
    rdfs:comment "Hit points restored, in the source game's hit points." .

ga:poise a owl:DatatypeProperty ;
    rdfs:label "poise" ;
    rdfs:comment "Resistance to being staggered. Not every game has it." .

ga:staminaCost a owl:DatatypeProperty ;
    rdfs:label "stamina cost" ;
    rdfs:comment "Stamina spent by one swing. Not every game has stamina." .

ga:refillsAtCheckpoint a owl:DatatypeProperty ;
    rdfs:label "refills at checkpoint" ;
    rdfs:comment "True when the item comes back full at a checkpoint. Not every game has checkpoints." .

# ---------------------------------------------------- what a game declares about itself

ga:maxPlayerHealth a owl:DatatypeProperty ; rdfs:domain ga:Game ;
    rdfs:label "max player health" .

ga:metresPerLengthUnit a owl:DatatypeProperty ; rdfs:domain ga:Game ;
    rdfs:label "metres per length unit" .

ga:maxArmourRating a owl:DatatypeProperty ; rdfs:domain ga:Game ;
    rdfs:label "max armour rating" ;
    rdfs:comment "The top of this game's armour scale." .

ga:damageReductionAtMaxArmour a owl:DatatypeProperty ; rdfs:domain ga:Game ;
    rdfs:label "damage reduction at max armour" ;
    rdfs:comment "Fraction of incoming damage removed at the top of the armour scale. With the max rating this fixes the scale as linear." .

ga:defaultStaminaCost a owl:DatatypeProperty ; rdfs:domain ga:Game ;
    rdfs:label "default stamina cost" ;
    rdfs:comment "What this game charges for a swing when the item never said." .

ga:wholeNumbersOnly a owl:DatatypeProperty ; rdfs:domain ga:Game ;
    rdfs:label "whole numbers only" ;
    rdfs:comment "True when this game stores damage, health and armour as integers." .

# ---------------------------------------------- what the receiving game's policy produced

ga:damageInTarget a owl:DatatypeProperty ; rdfs:label "damage in target" .
ga:lengthInTarget a owl:DatatypeProperty ; rdfs:label "length in target" .
ga:healInTarget a owl:DatatypeProperty ; rdfs:label "heal in target" .
ga:armourInTarget a owl:DatatypeProperty ; rdfs:label "armour in target" .
ga:staminaCostInTarget a owl:DatatypeProperty ; rdfs:label "stamina cost in target" .
ga:staminaCostDefaulted a owl:DatatypeProperty ;
    rdfs:label "stamina cost defaulted" ;
    rdfs:comment "True when the stamina cost in the target came from the target's declared default, because the item had none." .

files.rule:
# The conversion policy both games declare today: PROPORTIONAL.
#   damage and healing keep their share of a player's health
#   (7 of Blocky's 20 HP is 35%, and 35% of Ashen's 1,000 HP is 350);
#   length goes through metres;
#   armour keeps its share of damage removed, on each game's linear scale.
# This is a policy, not a fact. A game that wants absolute damage writes another
# rule. Lean does not check this file: it is shipped in every passport so that
# anyone can run it again and get the same numbers.
#
# EVERY arithmetic chain below is fully parenthesised, and that is load-bearing.
# Oxigraph's SPARQL parser (spargebra 0.5, upstream and in the engine's fork)
# groups chains to the RIGHT: it reads 7/20*1000 as 7/(20*1000) = 0.00035 and
# 8-3-2 as 8-(3-2) = 7. The SPARQL 1.1 grammar makes both left-associative.
# tests/test_verdicts.py pins the numbers so the bug cannot come back silently.
#
# It reads the customs declaration `?item ga:importTarget ?target` that the
# receiving game asserts, so one rule serves both directions.

PREFIX ga: <https://tesseractsemantics.com/ns/asset-passport/ga#>

CONSTRUCT {
  ?item ga:damageInTarget      ?dmg ;
        ga:lengthInTarget      ?len ;
        ga:healInTarget        ?heal ;
        ga:armourInTarget      ?arm ;
        ga:staminaCostInTarget ?stam ;
        ga:staminaCostDefaulted ?stamDefaulted .
}
WHERE {
  ?item ga:importTarget ?tgt ;
        ga:fromGame     ?src .
  ?src ga:maxPlayerHealth ?srcHp ; ga:metresPerLengthUnit ?srcM .
  ?tgt ga:maxPlayerHealth ?tgtHp ; ga:metresPerLengthUnit ?tgtM .
  OPTIONAL { ?tgt ga:wholeNumbersOnly ?w }
  BIND (COALESCE(?w, false) AS ?whole)

  OPTIONAL { ?item ga:baseDamage ?d }
  BIND (((?d / ?srcHp) * ?tgtHp) AS ?dRaw)
  BIND (IF(?whole, ROUND(?dRaw), ?dRaw) AS ?dmg)

  OPTIONAL { ?item ga:healAmount ?h }
  BIND (((?h / ?srcHp) * ?tgtHp) AS ?hRaw)
  BIND (IF(?whole, ROUND(?hRaw), ?hRaw) AS ?heal)

  OPTIONAL { ?item ga:length ?l }
  BIND (((?l * ?srcM) / ?tgtM) AS ?len)

  OPTIONAL {
    ?item ga:armourRating ?a .
    ?src ga:maxArmourRating ?srcMaxA ; ga:damageReductionAtMaxArmour ?srcRed .
    ?tgt ga:maxArmourRating ?tgtMaxA ; ga:damageReductionAtMaxArmour ?tgtRed .
  }
  BIND (((((?a / ?srcMaxA) * ?srcRed) / ?tgtRed) * ?tgtMaxA) AS ?aRaw)
  BIND (IF(?whole, ROUND(?aRaw), ?aRaw) AS ?arm)

  # Stamina exists only where the target declares a default for it. Where it
  # does not, ?def is unbound, the IF picks its third argument, which names an
  # unbound variable, and the binding is left empty: no stamina triple is made.
  OPTIONAL { ?item a ga:MeleeWeapon . ?tgt ga:defaultStaminaCost ?def }
  OPTIONAL { ?item ga:staminaCost ?own }
  BIND (IF(BOUND(?def), COALESCE(?own, ?def), ?noStamina) AS ?stam)
  BIND (IF(BOUND(?def), !BOUND(?own), ?noStamina) AS ?stamDefaulted)
}

files.souls_border:
@prefix ga:  <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix sh:  <http://www.w3.org/ns/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix c: <https://tesseractsemantics.com/ns/asset-passport/contract/souls#> .

# Ashen's border. Every shape here is a REFUSAL: an item that fails one does not
# enter the game. The values it reads are the ones the declared conversion
# policy produced, in Ashen's own units. Severity is left at its default
# (sh:Violation) on purpose: the verified evaluator ignores sh:severity, so a
# warning written here would refuse an item on one evaluator and admit it on the
# other. Warnings live in souls-loss.shacl.ttl.

c:Provenance a sh:NodeShape ;
    sh:targetClass ga:Item ;
    sh:property [ sh:path ga:fromGame ; sh:minCount 1 ;
        sh:message "Ashen admits no item that does not say which game its numbers are written in." ] .

c:NoRespawnAnchors a sh:NodeShape ;
    sh:targetClass ga:Item ;
    sh:property [ sh:path rdf:type ; sh:not [ sh:hasValue ga:RespawnAnchor ] ;
        sh:message "Ashen refuses respawn anchors. Death sends you to the last bonfire, and an item that moves that point removes the loop the game is built on." ] .

c:NoOneShots a sh:NodeShape ;
    sh:targetClass ga:Weapon ;
    sh:property [ sh:path ga:damageInTarget ; sh:minCount 1 ; sh:maxInclusive 600 ;
        sh:message "Ashen refuses a weapon that takes more than 60% of a player's 1,000 HP in one hit, or that arrives with no damage at all." ] .

c:ReachInRange a sh:NodeShape ;
    sh:targetClass ga:MeleeWeapon ;
    sh:property [ sh:path ga:lengthInTarget ; sh:minCount 1 ; sh:minInclusive 30 ; sh:maxInclusive 250 ;
        sh:message "Ashen's hitboxes assume a blade between 30 cm and 250 cm." ] ;
    sh:property [ sh:path ga:staminaCostInTarget ; sh:minCount 1 ;
        sh:message "Every swing in Ashen costs stamina." ] .

c:ArmourCap a sh:NodeShape ;
    sh:targetClass ga:Armour ;
    sh:property [ sh:path ga:armourInTarget ; sh:minCount 1 ; sh:maxInclusive 60 ;
        sh:message "Ashen refuses one piece of armour that absorbs more than 60% of a hit." ] .

c:HealCap a sh:NodeShape ;
    sh:targetClass ga:HealingConsumable ;
    sh:property [ sh:path ga:healInTarget ; sh:minCount 1 ; sh:maxInclusive 600 ;
        sh:message "Ashen refuses a heal above 60% of a player's HP in one use." ] .

files.blocky_border:
@prefix ga:  <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix sh:  <http://www.w3.org/ns/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix c: <https://tesseractsemantics.com/ns/asset-passport/contract/blocky#> .

# Blocky's border. Every shape is a refusal (see souls-border.shacl.ttl for why
# no warning lives here). Values are in Blocky's units: hit points out of 20,
# blocks, armour points out of 20.

c:Provenance a sh:NodeShape ;
    sh:targetClass ga:Item ;
    sh:property [ sh:path ga:fromGame ; sh:minCount 1 ;
        sh:message "Blocky admits no item that does not say which game its numbers are written in." ] .

c:NoOneShots a sh:NodeShape ;
    sh:targetClass ga:Weapon ;
    sh:property [ sh:path ga:damageInTarget ; sh:minCount 1 ; sh:maxInclusive 12 ;
        sh:message "Blocky refuses a weapon that takes more than 12 of a player's 20 HP in one hit." ] .

c:FitsTheTunnel a sh:NodeShape ;
    sh:targetClass ga:MeleeWeapon ;
    sh:property [ sh:path ga:lengthInTarget ; sh:minCount 1 ; sh:maxInclusive 2.0 ;
        sh:message "Blocky refuses a blade longer than 2 blocks: it would swing through the walls of a 1-block tunnel." ] .

c:ArmourCap a sh:NodeShape ;
    sh:targetClass ga:Armour ;
    sh:property [ sh:path ga:armourInTarget ; sh:minCount 1 ; sh:maxInclusive 8 ;
        sh:message "Blocky refuses one piece of armour above 8 armour points." ] .

c:HealCap a sh:NodeShape ;
    sh:targetClass ga:HealingConsumable ;
    sh:property [ sh:path ga:healInTarget ; sh:minCount 1 ; sh:maxInclusive 20 ;
        sh:message "Blocky refuses a heal above a full 20 HP." ] .

files.blocky_loss:
@prefix ga:  <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix sh:  <http://www.w3.org/ns/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix c: <https://tesseractsemantics.com/ns/asset-passport/contract/blocky#> .

# What an item loses on the way into Blocky. Every shape is a sh:Warning: the
# item still enters, and the passport says out loud which attribute had nowhere
# to go. Run on the SPARQL-compiling evaluator, which reads sh:severity.

c:NoPoise a sh:NodeShape ;
    sh:targetClass ga:Item ;
    sh:property [ sh:path ga:poise ; sh:maxCount 0 ; sh:severity sh:Warning ;
        sh:message "Blocky has no poise. This item's poise is dropped." ] .

c:NoStamina a sh:NodeShape ;
    sh:targetClass ga:Item ;
    sh:property [ sh:path ga:staminaCost ; sh:maxCount 0 ; sh:severity sh:Warning ;
        sh:message "Blocky has no stamina. This item's stamina cost is dropped." ] .

c:NoCheckpoints a sh:NodeShape ;
    sh:targetClass ga:Item ;
    sh:property [ sh:path ga:refillsAtCheckpoint ; sh:maxCount 0 ; sh:severity sh:Warning ;
        sh:message "Blocky has no checkpoints. This item will not refill: once used, it is gone." ] .
